if (pnpmConfig.wantedPackageManager) {
  if (pnpmConfig.pmOnFail) {
    pnpmConfig.wantedPackageManager.onFail = pnpmConfig.pmOnFail;
  } else if (pnpmConfig.wantedPackageManager.onFail == null) {
    pnpmConfig.wantedPackageManager.onFail = "download";
  }
}

if (cmd !== "setup" && !shouldSkipPmHandling(cmd, cliParams)) {
  if (context.wantedPackageManager != null) {
    const pm2 = context.wantedPackageManager;
    if (pm2.onFail !== "ignore") {
      if (pm2.name === "pnpm" && pm2.onFail === "download" && !isExecutedByCorepack()) {
        await switchCliVersion(config2, context);
      } else if (cliOptions.global) {
        globalWarn("Using --global skips the package manager check for this project");
      } else {
        checkPackageManager(pm2, { underCorepack: isExecutedByCorepack() });
        await syncEnvLockfile(config2, context);
      }
    }
  }
  if (cmd != null && !cliOptions.global) {
    for (const runtime of getWantedRuntimes(context)) {
      checkRuntime(runtime);
    }
  }
}

