      record.events[0]!.data = { kind: 'text', text: 'CORRUPT-PAYLOAD' };
      await writeFile(path, JSON.stringify(record));
    }
    if (corruption === 'missing') await rm(path);
    if (corruption === 'oversize') await writeFile(path, ' '.repeat(8193));
