    ['(step: DesktopV2ManagementStep, selector: string, label: string)', '(step, selector, label)'],
    ['let receipt: Awaited<ReturnType<typeof commands>>[number] | undefined;', 'let receipt;'],
    ['new Promise<void>', 'new Promise'],
