    await act(async () => {
      useStore.setState({ editorFileTreeError: null, editorFileTreeLoading: false });
    });
    expect(reveal).not.toHaveBeenCalled();
    await act(async () => {
      expect(useStore.getState().retryPendingTaskDetailEditor(request.nonce)).toBe(true);
